  card:[`${s.cardColor==='red'?'RED':'GREEN'} CARD`,s.card?'Your card has been dispensed. Continue the event.':`Press the glowing <strong>${s.cardColor==='red'?'紅卡 RED':'綠卡 GREEN'} button on your meter</strong>. The card comes out of its matching slot.`,s.card?'Continue dispensed card →':''],
  transfer:['PURPLE TRANSFER',`Transfer zone ${nodes[p.pos].transferGroup||''}. Select a taxi legal here. <strong>D and the first taxi bonus stay locked.</strong>`,'Keep current taxi →'],
  end:['PASS THE METER',`This turn’s roll and events are complete. <strong>Your order, taxi and point number stay saved.</strong>${p.bonusRolls?' Your card roll is saved for your next turn.':''} Pass to the next driver.`,s.players.length===1?'Next dice turn →':'Next player →'],
  delivered:['PASSENGER DELIVERED','Arrived. Unused dice steps are discarded. <strong>Settle this entire order, then pass to the next driver.</strong>','Open receipt →'],
