$('#fullscreen-btn').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Use your browser’s full-screen option to expand the game.');}});
document.addEventListener('fullscreenchange',()=>{const full=!!document.fullscreenElement,button=$('#fullscreen-btn');button.textContent=full?'↙':'⛶';button.setAttribute('aria-label',full?'Exit full screen':'Enter full screen');button.title=full?'Exit full screen · 退出全屏':'Full screen · 全屏';scheduleWorkspaceFit();});
function challengeInfo(c){const p=game.player,j=p.job,reg=nodes[p.pos].region;return {
 destination:{question:'Point to and read your current destination aloud.',check:station(j.to)+' · '+(nodes[j.to].zh||'')},
 greet:{question:'Say a greeting and confirm where your passenger is going.',check:'For example: “Hello! We’re going to '+station(j.to)+', correct?”'},
 luggage:{question:'Explain what to do before helping with a passenger’s luggage.',check:'Ask for the passenger’s permission before helping.'},
 taxi:{question:'Say where your current '+TAXIS[p.taxi].name.toLowerCase()+' can travel in this game.',check:TAXIS[p.taxi].range+' · '+TAXIS[p.taxi].rangeZh},
 landmark:{question:'Name one place and its landmark in '+REGIONS[reg].name+'.',check:'Use any matching place and landmark shown on the map. Example: '+{islands:'Ngong Ping — Tian Tan Buddha',nt:'Yuen Long — Tsui Sing Lau Pagoda',kowloon:'West Kowloon — M+',hk:'Victoria Peak — The Peak'}[reg]},
 fare:{question:'Airport → Tung Chung: shortest 15, actually driven 25. What is the base fare?',check:'75 game coins. Only the 15 shortest steps count: 15 × 5.'},
 receipt:{question:'Your passenger asks for proof of the ride. What do you do?',check:'Provide a receipt and remind the passenger to record the taxi’s number plate.'}
 }[c.challenge];}
function showCard(card){if(!card)return;clearInterval(cardTimer);const d=$('#event-dialog');if(d.open)d.close();const quiz=card.effect.startsWith('challenge');$('#event-body').innerHTML=`<div class="event-layout"><img class="event-art" src="assets/${card.color}-${card.index+1}.webp" alt="Original ${card.id} ${esc(card.title)} card"><div class="event-details"><div class="eyebrow">${card.id} · ${card.color==='red'?'ROAD':'SERVICE'} EVENT</div><h2>${esc(card.title)}</h2><h3>${esc(card.zh)}</h3><p>${esc(card.text)}</p><div id="challenge-area"></div>${quiz?'':'<button class="button forest" id="apply-card">Apply this card →</button>'}<div class="event-limits-note">This draw counts even if a challenge is missed. Per order: red ${game.player.job.counts.red}/2 · green ${game.player.job.counts.green}/2. This point cannot trigger again.</div></div></div>`;d.showModal();
 if(!quiz){$('#apply-card').addEventListener('click',()=>finishCard(false));save();return;}
 const info=challengeInfo(card),expires=card.expiresAt||(card.expiresAt=Date.now()+20000);$('#challenge-area').innerHTML=`<div class="challenge-time"><span>20 SECONDS · 意思正確即可</span><strong id="challenge-count">20s</strong></div><div class="challenge-question">${esc(info.question)}</div><div id="spoken-check"><${card.challenge==='fare'?'input':'textarea'} class="speak-answer" id="spoken-answer" aria-label="Your challenge answer" ${card.challenge==='fare'?'type="number" placeholder="Base fare in coins"':'placeholder="Say your answer aloud, or type it here."'}>${card.challenge==='fare'?'':'</textarea>'}<button class="button forest" style="margin-top:10px" id="reveal-check">${card.challenge==='fare'?'Check my fare →':'I’ve answered · reveal the check →'}</button></div><button class="text-button" style="margin-top:10px" id="skip-challenge">Skip · no reward</button>`;
 cardTimer=setInterval(()=>{const left=Math.max(0,Math.ceil((expires-Date.now())/1000));if($('#challenge-count'))$('#challenge-count').textContent=left+'s';if(!left)finishCard(false);},150);
 $('#reveal-check').addEventListener('click',()=>{if(Date.now()>expires)return finishCard(false);if(card.challenge==='fare')return finishCard(Number($('#spoken-answer').value)===75);$('#spoken-check').innerHTML=`<div class="answer-check">${esc(info.check)}<br><br>Other drivers check the meaning. In solo mode, compare your answer honestly; no microphone or speech recording is used.</div><div class="challenge-actions"><button class="button forest" id="answer-correct">Meaning correct · claim reward ✓</button><button class="button outline" id="answer-incorrect">Not yet · no reward</button></div>`;$('#answer-correct').addEventListener('click',()=>finishCard(Date.now()<=expires));$('#answer-incorrect').addEventListener('click',()=>finishCard(false));});$('#skip-challenge').addEventListener('click',()=>finishCard(false));save();
}
function finishCard(success){clearInterval(cardTimer);const text=game.resolveCard(success);$('#event-dialog').close();render();toast(text);beep(success?760:420);}
$('#event-dialog').addEventListener('cancel',e=>e.preventDefault());
function showReceipt(){const s=game.state,r=s.receipt;if(!r)return;clearInterval(cardTimer);const d=$('#event-dialog');if(d.open)d.close();$('#event-body').innerHTML=`<div class="receipt-layout"><div class="receipt-stamp">ORDER COMPLETE · 已送達</div><h2>One whole ride. Settled.</h2><p>${esc(station(r.from))} ↓ ${esc(station(r.to))}</p><div class="receipt-total">+${r.amount}<span>GAME COINS · 本單收入</span></div><div class="receipt-breakdown"><div><span>Locked D · ${r.shortest} × 5</span><b>${r.shortest*5}</b></div><div><span>First valid taxi · ${TAXIS[r.initialTaxi].name}</span><b>+${r.bonus}</b></div><div><span>Pending card rewards</span><b>+${r.rewards}</b></div><div><span>Actual steps · detours add no fare</span><b>${r.actual}</b></div><div><span>Cards used this order</span><b>Red ${r.counts.red}/2 · Green ${r.counts.green}/2</b></div></div><p>Arrival discarded all unused steps.<br>Immediate expenses have already reduced the net balance.<br><strong>The next player now takes the meter. Other unfinished orders stay saved.</strong></p><button class="button forest" id="receipt-next">${s.closing&&!s.players.some(p=>p.job)?'Finish the shift →':s.players.length===1?'Find the next passenger →':'Pass the meter to the next driver →'}</button></div>`;d.showModal();$('#receipt-next').addEventListener('click',()=>{d.close();game.next();render();});beep(820,.15);}
function showFinished(){const s=game.state,rank=game.rankings(),best=rank[0],winners=rank.filter(p=>p.coins===best.coins&&p.trips===best.trips),d=$('#event-dialog');if(d.open)d.close();$('#event-body').innerHTML=`<div class="receipt-layout"><div class="eyebrow" style="justify-content:center">SHIFT COMPLETE · 收工</div><h2>${winners.length>1?'A shared first place.':'Top of the meter.'}</h2><p>${esc(winners.map(p=>p.name).join(' & '))}</p><div class="receipt-total">${best.coins}<span>NET GAME COINS</span></div><div class="finished-leaderboard">${rank.map((p,i)=>`<div class="finished-row"><span>${i+1}. ${esc(p.name)} · ${p.trips} completed orders</span><b>${p.coins}</b></div>`).join('')}</div><p>Ranked by net coins, then completed orders.<br>If both match, the result is shared.</p><button class="button forest" id="play-again">Start another shift ↗</button><button class="text-button" id="close-results" style="margin-top:15px">Explore the original map</button></div>`;d.showModal();$('#play-again').addEventListener('click',()=>{d.close();setup();});$('#close-results').addEventListener('click',()=>d.close());}
function openContent(type){const b=$('#content-body');if(type==='original-map')renderOriginalMap(b,started?nodes[game.player.pos]:undefined);else if(type==='rules')renderRules(b);else if(type==='cards')renderCollection(b);else if(type==='journal')renderJournal(b);else renderStory(b);openDialog($('#content-dialog'));}
function renderJournal(body){body.innerHTML=`<div class="eyebrow">SHIFT JOURNAL · 行車日誌</div><h2>Every turn, recorded.</h2><p class="dialog-lead">${started?'Your orders, taxi draws, movement and card events from this shift.':'Start a shift to record your journey through Hong Kong.'}</p><div class="journal-list">${started?game.state.log.map(t=>`<div class="log-entry">${esc(t)}</div>`).join(''):'<div class="log-entry">Your first passenger is waiting.</div>'}</div>`;}
function renderRules(b){b.innerHTML=`<div class="eyebrow">PROJECT RULES · 遊戲規則</div><h2>One dice turn. Then the next driver.</h2><p class="dialog-lead">Each player gets one dice roll per turn, including the taxi draw. Draws pass immediately; movement rolls pass after their steps and landing effects. Every player keeps their unfinished order, taxi and point number. The map automatically zooms to the active taxi at the start of each turn.</p><div class="rules-flow"><article><h3>Get a random order</h3><p>Two different yellow locations are chosen from all <strong>54 stops</strong>. The map finds your pick-up automatically. Confirm the order to draw a taxi. Pick-up is step zero; entering each next dot, including the destination, costs one step.</p></article><article><h3>Tap 空車 / VACANT to draw</h3><p>Every player has <strong>one dice roll per turn</strong>, including the taxi draw. Tap <strong>空車 / VACANT</strong>: <strong>1–2 blue, 3–4 green, 5–6 red.</strong> Before a valid draw, no taxi appears on the map. An unsuitable colour places no vehicle and immediately passes to the next player. Retry only on your next turn. A valid draw places that taxi and passes as well; driving begins on your next turn.</p></article><article><h3>Lock D, then tap 空車 to drive</h3><p>The first valid draw automatically locks shortest legal steps <strong>D</strong> and the taxi bonus, including necessary purple transfers. Base fare stays <strong>D × 5</strong>. On later turns, tap 空車 / VACANT once for 1–6 movement steps. This turn’s allowance is then used. Choose connected road dots.</p></article><article><h3>Explore the map freely</h3><p><strong>Zoom, drag and switch districts whenever you wish.</strong> The display’s − and + adjust zoom immediately. ✓ keeps a manual view; X undoes unconfirmed view changes. These controls are optional. They never block dice, use steps, move taxis or pass a turn. Each new turn automatically focuses the active player’s saved point.</p></article><article><h3>Resolve the final-dot event</h3><p>Only the final stop of a dice roll triggers red/green events; passing a dot does not. Press the matching red/green meter button to dispense a card. Cards requesting another roll are saved for that player’s next turn, using that turn’s one roll and the same 空車 sign. They never allow a second roll in the current turn. Card movement triggers no new cards. Finish on a purple dot in one of <strong>35 transfer zones</strong> to select a legal taxi. D, the first bonus and event records stay locked.</p></article><article><h3>Deliver, settle, then pass</h3><p>Arrival discards spare steps. Collect <strong>D × 5 + first taxi bonus + pending rewards</strong>. Expenses reduce the net balance immediately. After each dice move and landing effects, switch players. Unfinished orders resume next turn. Resolve movement and landing effects before passing. Saved card rolls wait until that player’s next turn. A new order is issued only after that player’s previous delivery.</p></article></div><div class="taxi-rule-row">${Object.entries(TAXIS).map(([c,t])=>`<div class="taxi-rule"><img src="${taxiAsset(c)}" alt="${t.name}"><b>${t.name}<span>+${t.bonus}</span></b><p>${t.range}</p><small>${t.zh} · ${t.rangeZh}</small></div>`).join('')}</div><div class="rules-limits"><strong>Per-order event limits</strong><br>Maximum 2 red and 2 green cards. A card counts when drawn, even if the answer is wrong. Each event point triggers only once per order. Transfers and view changes never reset the record. Extra red/green dots act as ordinary roads.<br><br><strong>Connected roads only</strong><br>Travel on the illustrated connected dots; no sea jumps. Every road dot counts. The Hong Kong–Zhuhai–Macao Bridge has no game path dots.<br><br><strong>When time ends</strong><br>No new orders, taxi draws or event cards. Orders with no valid taxi close without a fare. Finish orders that already have a taxi by shortest legal routes, continuing the same dice-turn rotation. Keep the fixed fare, first taxi bonus and earlier rewards. Highest net coins wins, then most completed orders; share a tie if both match.</div><div class="fare-example" style="margin-top:15px">AIRPORT → TUNG CHUNG<strong>15 shortest steps × 5 = 75 base coins</strong>Even after 25 actual steps: blue earns 85, green 81, red 75, before other rewards or charges.</div><p class="web-notes">Cultural tasks allow 20 seconds. Say or type an answer; other players check its meaning, or use the solo answer guide. No microphone is recorded. Solo or 2–6 drivers share one device with local autosave. Original duration: 60 minutes; 15/30-minute practice options use the same ending rules. Game coins are scores only.</p><a class="button forest" style="display:inline-flex;margin-top:12px" href="assets/rules-revised.docx" download>Original project rules DOCX ↧</a>`;}

function renderCollection(body,color='red'){body.innerHTML=`<div class="eyebrow">THE ORIGINAL CARD COLLECTION</div><h2>Every stop changes the story.</h2><p class="dialog-lead">Ten road events. Ten service events. All original artwork and effects, brought into the game.</p><div class="card-tabs"><button data-deck="red" class="${color==='red'?'selected':''}">Red · Road events</button><button data-deck="green" class="${color==='green'?'selected':''}">Green · Service events</button></div><div class="card-grid">${CARDS[color].map((c,i)=>`<button class="collection-card" data-card-index="${i}"><img src="assets/${color}-${i+1}.webp" alt="${c.id} ${esc(c.title)}"><small>${c.id} · ${esc(c.title)}</small></button>`).join('')}<div class="collection-card"><img src="assets/${color}-back.webp" alt="Original ${color} shared card back"><small>Shared card back</small></div></div>`;$$('[data-deck]').forEach(b=>b.addEventListener('click',()=>renderCollection(body,b.dataset.deck)));$$('[data-card-index]').forEach(b=>b.addEventListener('click',()=>{const c=CARDS[color][+b.dataset.cardIndex];body.innerHTML=`<button class="text-button" id="collection-back">← Back to the collection</button><div class="event-layout" style="margin-top:25px"><img class="event-art" src="assets/${color}-${+b.dataset.cardIndex+1}.webp" alt="${esc(c.title)}"><div class="event-details"><div class="eyebrow">${c.id} · ORIGINAL CARD</div><h2>${esc(c.title)}</h2><h3>${esc(c.zh)}</h3><p>${esc(c.text)}</p></div></div>`;$('#collection-back').addEventListener('click',()=>renderCollection(body,color));}));}
function renderStory(body){body.innerHTML=`<div class="eyebrow">FROM THE TABLE TO THE CITY</div><h2>Hong Kong, on the meter.</h2><p class="dialog-lead">A tangible board game that turns Hong Kong taxi culture into something you can explore, experience, and remember.</p><img class="story-hero" src="assets/table.webp" alt="Four people playing the original Hong Kong On The Meter physical board game"><p class="story-text">HONG KONG ON THE METER brings three-colour taxis, traditional meters, regional routes and cultural encounters into an interactive game. The original physical concept combines miniature taxis with magnets, Hall sensors and a flexible screen. This web edition translates those interactions into a playable map: rotate the meter, drive from dot to dot, draw cards and deliver passengers.</p><div class="hardware-grid"><div class="hardware-item"><img src="assets/meter-side.webp" alt="Original taxi meter side view"><b>The tactile meter</b><p>The VACANT sign becomes your dice. Red and green buttons dispense the two card decks.</p></div><div class="hardware-item"><img src="assets/screen-angle.webp" alt="Original flexible map screen"><b>The flexible map</b><p>Your original illustrated geography connects Islands, the New Territories, Kowloon and Hong Kong Island.</p></div><div class="hardware-item"><img src="assets/screen-controls.webp" alt="Original screen controls including zoom and confirm"><b>Hands-on exploration</b><p>Zoom, explore and find the next stop. Physical controls become the map tools of this web edition.</p></div></div><p class="web-notes">All map, taxi, meter, card, screen and gameplay images in this edition come from the project’s supplied artwork. The web rules use the project’s latest rules poster.</p>`;}
async function init(){try{const [response]=await Promise.all([fetch('assets/board.json'),loadNativeMap()]);if(!response.ok)throw Error('Map data unavailable');nodes=await response.json();game=new Game(nodes);try{saved=JSON.parse(localStorage.getItem(STORAGE)||localStorage.getItem('hk-on-the-meter-v8')||localStorage.getItem('hk-on-the-meter-v7')||localStorage.getItem('hk-on-the-meter-v6')||'null');if(![6,7,8,9].includes(saved?.version))saved=null;}catch{saved=null;}if(saved)$('#resume-btn').hidden=false;names();fitWorkspace();renderProgress();renderDisplayControls();let lastSave=0;setInterval(()=>{const now=performance.now(),delta=(now-lastTick)/1000;lastTick=now;if(!started||game.state.paused)return;const ended=game.tick(delta);updateClock();if(ended){render();toast('Time is up: finish this passenger by the shortest legal route. No new cards or orders.');}if(now-lastSave>5000){save();lastSave=now;}},500);}catch(e){toast('The original map could not load. Please refresh and try again.');console.error(e);}}
init();
